<?php get_header();$type=get_post_type();$back=['post'=>'news-stories','gopa_course'=>'storm-academy','gopa_field'=>'about-us','gopa_hub'=>'get-involved']; ?><main id="main" class="page-main"><div id="top"></div><?php while(have_posts()):the_post(); ?><article class="container article"><a class="eyebrow" href="<?php echo esc_url(gopa_url($back[$type]??'events-resources')); ?>">← <?php echo esc_html(gopa_text('back_movement')); ?></a><header><span class="eyebrow"><?php echo esc_html(get_post_meta(get_the_ID(),'gopa_label',true)); ?></span><h1><?php the_title(); ?></h1></header><?php if(has_post_thumbnail()): ?><div class="article-image"><?php the_post_thumbnail('large'); ?></div><?php endif; ?><div class="article-content"><?php the_content(); ?><?php $url=get_post_meta(get_the_ID(),'gopa_url',true);if($url): ?><p><a class="button" href="<?php echo esc_url($url); ?>"><?php echo esc_html(get_post_meta(get_the_ID(),'gopa_button',true)?:gopa_text($type==='gopa_resource'?'open_resource':'register_action')); ?> ↗</a></p><?php elseif(in_array($type,['gopa_course','gopa_event','gopa_hub'],true)): ?><p><a class="button" href="<?php echo esc_url($type==='gopa_course'?add_query_arg('interest','STORM Academy registration',gopa_url('contact')):gopa_url('contact')); ?>"><?php echo esc_html(gopa_text('enquire_action')); ?> ↗</a></p><?php endif; ?></div></article><?php endwhile; ?></main><?php get_footer(); ?>
